function LogoWordmark({ iconH, color }: { iconH: number; color?: string }) {
  const scale = (iconH * 4) / 10 / WORD_CAP;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={`${WORD_X} ${WORD_Y} ${WORD_W} ${WORD_H}`}
      width={WORD_W * scale}
      height={WORD_H * scale}
      aria-hidden
      className="shrink-0"
    >
      <path fill={color ?? "currentColor"} d={WORD_PATH} />
    </svg>
  );
}

export function Logo({ variant = "full", size = 32, color, className, style }: LogoProps) {
  const iconH = size;
  const mark = <LogoMark height={iconH} color={color} />;
  const word = <LogoWordmark iconH={iconH} color={color} />;
  const root = cn("inline-flex items-center text-foreground", variant === "full" && "gap-3", className);

  return (
    <span role="img" aria-label={WORDMARK} className={root} style={style}>
      {variant === "text" ? null : mark}
      {variant === "icon" ? null : word}
    </span>
  );
}
